package fraymus.workspace;
import org.junit.Test;
import static org.junit.Assert.*;
import org.json.*;
import java.nio.file.*;
import java.util.*;

public class Recovery066Test {
    static JSONObject task(double center,double width){return new JSONObject().put("angleDeg",20).put("frictionRatio",1.05).put("centerM",center).put("halfWidthM",width);}
    @Test public void initialPoliciesRetainOldChoicesAndRefusalDomain(){
        for(Object raw:RecoveryStudy066.cases(false)){var t=(JSONObject)raw;var old=DecisionPolicy065.plan(t);var p=RecoveryPolicy066.initial(t);for(String m:DecisionPolicy065.METHODS)assertTrue(old.getJSONObject("decisions").getJSONObject(m).similar(p.getJSONObject("decisions").getJSONObject(m)));for(String m:List.of("blind","observed")){var d=p.getJSONObject("decisions").getJSONObject(m);assertTrue(d.getBoolean("execute"));assertEquals(!old.getJSONObject("decisions").getJSONObject("pooled").getBoolean("execute"),d.getBoolean("recover"));}}
        for(Object raw:RecoveryStudy066.cases(true)){var p=RecoveryPolicy066.initial((JSONObject)raw);for(String m:RecoveryPolicy066.METHODS)assertFalse(p.getJSONObject("decisions").getJSONObject(m).getBoolean("execute"));}
        assertThrows(IllegalArgumentException.class,()->RecoveryPolicy066.initial(task(.1,.012).put("hiddenRetry",true)));
    }
    @Test public void inverseAndBoundsUseOnlyTheSelectedState(){
        var t=task(.13,.012);var state=RecoveryPolicy066.predicted(t,.24);var p=RecoveryPolicy066.replan(t,state);assertTrue(p.getBoolean("correct"));assertEquals(.13,p.getDouble("predictedEndpointM"),1e-12);assertTrue(Math.abs(p.getDouble("deltaVelocityMps"))<=.16);
        var accelerating=task(.2,.045).put("frictionRatio",.9);var a=RecoveryPolicy066.replan(accelerating,RecoveryPolicy066.predicted(accelerating,.24));assertTrue(Math.abs(a.getDouble("deltaVelocityMps"))<=.16);
        var measured=WorldFrames.copy(state).put("kind","measured").put("nearPoints",1).put("rotationDeg",0).put("normalMps",0).put("angularSpeedRadps",0);assertTrue(RecoveryPolicy066.replan(t,measured).getBoolean("correct"));
        for(String field:List.of("nearPoints","rotationDeg","normalMps","angularSpeedRadps")){var invalid=WorldFrames.copy(measured).put(field,field.equals("nearPoints")?0:99);assertFalse(RecoveryPolicy066.replan(t,invalid).getBoolean("correct"));}
        assertFalse(RecoveryPolicy066.replan(t,WorldFrames.copy(measured).put("distanceM",.3)).getBoolean("correct"));assertFalse(RecoveryPolicy066.replan(task(.6,.005),state).getBoolean("correct"));
        measured.put("distanceM",.09);assertTrue(p.similar(RecoveryPolicy066.replan(t,RecoveryPolicy066.predicted(t,.24))));assertFalse(p.similar(RecoveryPolicy066.replan(t,measured)));
        var stop=RecoveryPolicy066.replan(task(.012,.005),new JSONObject().put("kind","predicted").put("distanceM",.01).put("tangentMps",.03));assertEquals(.012,stop.getDouble("predictedEndpointM"),1e-12);
    }
    @Test public void attemptedRecoveryPaysForFailuresAndEveryUsedOperation(){
        var t=task(.13,.012);var decision=new JSONObject().put("execute",true).put("speedMps",.24).put("method","observed");var record=new JSONObject().put("summary",new JSONObject().put("endpointM",.13)).put("timing066",new JSONObject().put("nativeWallMillis",12)).put("correctionPlan",new JSONObject().put("correct",true).put("deltaVelocityMps",.04));
        var o=RecoveryPolicy066.outcome(t,decision,record);assertEquals(.92,o.getDouble("utility"),1e-12);assertEquals(.08,o.getDouble("logicalCost"),1e-12);assertEquals(2,o.getInt("actions"));assertEquals(.28,o.getDouble("absoluteImpulseNs"),1e-12);
        decision.put("method","blind");assertEquals(.95,RecoveryPolicy066.outcome(t,decision,record).getDouble("utility"),1e-12);
        decision.put("method","observed");record.getJSONObject("summary").put("endpointM",0);record.getJSONObject("correctionPlan").put("correct",false).put("deltaVelocityMps",0);o=RecoveryPolicy066.outcome(t,decision,record);assertEquals(-2.06,o.getDouble("utility"),1e-12);assertTrue(o.getBoolean("executed"));assertFalse(o.getBoolean("success"));
        var refused=RecoveryPolicy066.outcome(t,new JSONObject().put("execute",false),null);assertEquals(-.15,refused.getDouble("utility"),0);assertFalse(refused.has("endpointM"));assertEquals(0,refused.getInt("observations"));assertThrows(IllegalStateException.class,()->RecoveryPolicy066.outcome(t,new JSONObject().put("execute",false),record));
    }
    @Test public void qualificationRequiresObservationBenefitCompletionAndRecovery(){
        var e=new JSONObject().put("pairedObservedMinus",new JSONObject().put("fixed",new JSONObject().put("meanDelta",.1)).put("pooled",new JSONObject().put("meanDelta",.1)).put("blind",new JSONObject().put("meanDelta",.05))).put("methods",new JSONObject().put("observed",new JSONObject().put("allTaskSuccessRate",.5).put("allTaskMissRate",.2).put("recoveryRate",.3)));
        assertTrue(RecoveryStudy066.qualifies(e));for(String key:List.of("fixed","pooled","blind")){var copy=WorldFrames.copy(e);copy.getJSONObject("pairedObservedMinus").getJSONObject(key).put("meanDelta",0);assertFalse(RecoveryStudy066.qualifies(copy));}for(String key:List.of("allTaskSuccessRate","allTaskMissRate","recoveryRate")){var copy=WorldFrames.copy(e);copy.getJSONObject("methods").getJSONObject("observed").put(key,key.equals("allTaskMissRate")?.21:0);assertFalse(RecoveryStudy066.qualifies(copy));}
        assertEquals("agent",ChatPolicy044.route("Report the bounded recovery study and replanning costs",new JSONObject(),false));
    }
    @Test public void freshTasksAndLosslessContextRetainSubgroupsAndNulls(){
        var old=new HashSet<String>();for(Object raw:DecisionStudy065.cases(false))old.add(WorldFrames.hash((JSONObject)raw));var rows=new JSONArray();for(Object raw:RecoveryStudy066.cases(false)){var t=(JSONObject)raw;assertFalse(old.contains(WorldFrames.hash(t)));var results=new JSONObject();for(String m:RecoveryPolicy066.METHODS)results.put(m,new JSONObject().put("outcome",RecoveryPolicy066.outcome(t,new JSONObject().put("execute",false),null)));rows.put(new JSONObject().put("task",t).put("plan",RecoveryPolicy066.initial(t)).put("results",results));}
        var original=new JSONObject().put("recovery066",new JSONObject().put("lastCompleted",new JSONObject().put("evaluation",RecoveryStudy066.evaluation(rows)).put("shiftedEvaluation",RecoveryPolicy066.evaluate(rows,true))));String hash=WorldFrames.hash(original);var compact=RecoveryContext066.project(original);assertEquals(hash,WorldFrames.hash(original));assertTrue(compact.toString().length()<original.toString().length()*.65);var study=compact.getJSONObject("recovery066").getJSONObject("lastCompleted");var columns=study.getJSONObject("tableColumns066");restore(study.getJSONObject("evaluation"),columns);restore(study.getJSONObject("shiftedEvaluation"),columns);study.remove("tableColumns066");study.remove("tableMeaning066");assertTrue(original.similar(compact));
    }
    static void restore(JSONObject e,JSONObject columns){for(String name:List.of("methods","pairedObservedMinus")){var table=e.getJSONObject(name);var cols=columns.getJSONArray(table.getString("columnsRef"));var values=new JSONObject();for(Object raw:table.getJSONArray("rows")){var row=(JSONArray)raw;var metrics=new JSONObject();for(int i=0;i<cols.length();i++)metrics.put(cols.getString(i),row.get(i+1));values.put(row.getString(0),metrics);}e.put(name,values);}var groups=e.optJSONObject("subgroups");if(groups!=null)for(String key:groups.keySet())restore(groups.getJSONObject(key),columns);}
    @Test public void nativeStudyParityRealCorrectionColdHistoryStopAndTampering()throws Exception{
        var root=Files.createTempDirectory("fraynix-recovery066-");System.out.println("EDITION066_NATIVE_ROOT="+root);String id,hash;JSONObject job;
        try(var b=new BrainService(root)){id=b.start(new JSONObject().put("kind","bounded-recovery").put("autoPromote",false)).getString("id");waitFor(b);job=b.read(id);Files.writeString(root.resolve("original-attempt.json"),job.toString());assertEquals(job.optString("reason"),"completed",job.getString("status"));RecoveryStudy066.audit(job);Files.writeString(root.resolve("original-experiment.json"),job.toString());System.out.println("RECOVERY066="+job.getJSONObject("evaluation066"));hash=WorldFrames.hash(job);
            assertEquals(364,job.getInt("progress"));assertTrue(job.getInt("nativeExecutions")>=188);assertEquals(1,b.activePolicy().getInt("version"));JSONObject corrected=null;
            for(Object raw:job.getJSONArray("tasks066")){var row=(JSONObject)raw;var observed=row.getJSONObject("results").getJSONObject("observed").getJSONObject("record");if(observed.has("correctionReceipt")){corrected=observed;break;}}assertNotNull("A real bounded impulse must occur",corrected);final JSONObject record=corrected;
            tamperRecord(record,r->r.getJSONObject("correctionPlan").getJSONObject("state").put("distanceM",999));tamperRecord(record,r->r.getJSONObject("correctionReceipt").getJSONObject("after").getJSONArray("position").put(0,99));tamperRecord(record,r->r.getJSONObject("correctionReceipt").put("worldId",UUID.randomUUID().toString()));tamperRecord(record,r->r.put("correctionPlannedAt","2099-01-01T00:00:00Z"));
            tamper(job,j->j.getJSONArray("tasks066").getJSONObject(0).getJSONObject("results").getJSONObject("observed").getJSONObject("outcome").put("utility",999));tamper(job,j->j.getJSONArray("shifted066").getJSONObject(0).getJSONObject("results").getJSONObject("observed").put("record",record));tamper(job,j->j.getJSONArray("tasks066").put(1,j.getJSONArray("tasks066").getJSONObject(0)));
            var query=new JSONObject().put("jobId",id).put("index",0).put("shifted",false);var trace=b.recoveryTrace066(query);Files.writeString(root.resolve("trace.json"),trace.toString());assertEquals(46,trace.getJSONObject("results").getJSONObject("observed").getJSONArray("series").length());b.recoveryState066().getJSONObject("lastCompleted").getJSONObject("evaluation").put("qualified","changed");assertEquals(job.getJSONObject("evaluation066").getBoolean("qualified"),b.recoveryState066().getJSONObject("lastCompleted").getJSONObject("evaluation").getBoolean("qualified"));
        }
        try(var b=new BrainService(root)){assertEquals(hash,WorldFrames.hash(b.read(id)));assertTrue(new JSONObject(Files.readString(root.resolve("trace.json"))).similar(b.recoveryTrace066(new JSONObject().put("jobId",id).put("index",0).put("shifted",false))));String stopped=b.start(new JSONObject().put("kind","bounded-recovery")).getString("id");b.cancel(stopped);waitFor(b);assertEquals("cancelled",b.read(stopped).getString("status"));assertEquals(id,b.recoveryState066().getJSONObject("lastCompleted").getString("jobId"));assertEquals(hash,WorldFrames.hash(b.read(id)));}
    }
    static void waitFor(BrainService b)throws Exception{long until=System.nanoTime()+900_000_000_000L;while(b.state().getBoolean("busy")&&System.nanoTime()<until)Thread.sleep(600);assertFalse(b.state().getBoolean("busy"));}
    static void tamper(JSONObject job,java.util.function.Consumer<JSONObject> edit){var copy=WorldFrames.copy(job);edit.accept(copy);assertThrows(IllegalStateException.class,()->RecoveryStudy066.audit(copy));}
    static void tamperRecord(JSONObject record,java.util.function.Consumer<JSONObject> edit){var copy=WorldFrames.copy(record);copy.remove("sha256");edit.accept(copy);copy.put("sha256",WorldFrames.hash(copy));assertThrows(IllegalStateException.class,()->RecoveryTrial066.verify(copy));}
}
